const wait=async test=>{for(let i=0;i<300;i++){if(test())return;await new Promise(resolve=>setTimeout(resolve,20));}throw Error('UI wait timed out');};
const check=(name,test)=>{if(!test)throw Error(name);smoke.checks.push(name);};
const click=selector=>{const node=document.querySelector(selector);if(!node)throw Error('Missing '+selector);node.click();};
const untilSaved=()=>wait(()=>!document.querySelector('#editor').open);
(async()=>{
  try{
    await wait(()=>!document.querySelector('#app').hidden&&document.querySelector('.calendarEvent'));
    check('saved login opens calendar',document.querySelector('#chooser').hidden&&document.querySelector('#sessionLoading').hidden&&smoke.persisted);
    check('current-time line exists',!!document.querySelector('.currentTimeLine'));
    check('deadline marker exists',!!document.querySelector('.deadlineMarker'));
    click('.deadlineMarker');check('deadline marker navigates to tasks',!!document.querySelector('.deadlineCard'));click('footer [data-view="day"]');
    check('foreign visible event excluded from own list',![...document.querySelectorAll('.dayEvents h3')].some(node=>node.textContent==='Foreign visible'));
    click('.personalToggle');check('hide events',!!document.querySelector('.personalHidden'));click('#nextWeek');await new Promise(resolve=>setTimeout(resolve,450));check('hide survives navigation',!!document.querySelector('.personalHidden'));click('#todayButton');await new Promise(resolve=>setTimeout(resolve,450));
    click('#dateTitle');check('monthly view renders',document.querySelectorAll('.monthDay').length===42);
    check('month fits mobile width',document.documentElement.scrollWidth<=innerWidth+1);
    check('monthly event title is plain text',!document.querySelector('.monthDay img')&&!window.injected&&document.querySelector('.monthDay').parentElement.textContent.includes('<img'));
    click('.monthDay.today');check('month day opens calendar',!!document.querySelector('.sharedCalendar'));
    click('#add');click('#addEventKind');check('new event defaults public',document.querySelector('#space').value==='shared');
    check('date fields fit mobile editor',document.querySelector('#endsAt').getBoundingClientRect().right<=innerWidth);
    const start=document.querySelector('#startsAt'),end=document.querySelector('#endsAt');
    start.value=start.value.slice(0,10)+'T10:00';start.dispatchEvent(new Event('input'));check('end follows start',end.value.endsWith('T11:00'));
    end.value=start.value.slice(0,10)+'T12:30';end.dispatchEvent(new Event('input'));start.value=start.value.slice(0,10)+'T11:00';start.dispatchEvent(new Event('input'));check('manual end preserved',end.value.endsWith('T12:30'));
    document.querySelector('#title').value='Smoke saved event';document.querySelector('#eventForm').requestSubmit();await untilSaved();await wait(()=>document.querySelector('#spaces').textContent.includes('Smoke saved event'));check('event saved and shown',true);
    const added=[...document.querySelectorAll('.calendarEvent')].find(node=>node.textContent.includes('Smoke saved event'));added.click();click('#copy');await untilSaved();await wait(()=>document.querySelectorAll('.calendarEvent.joint').length>=2);check('shared participation expands both columns',true);
    [...document.querySelectorAll('.calendarEvent')].find(node=>node.textContent.includes('Smoke saved event')).click();click('#copy');await untilSaved();
    smoke.offline=true;const pushWrites=smoke.writes;[...document.querySelectorAll('.calendarEvent')].find(node=>node.textContent.includes('Smoke saved event')).click();click('#copy');await untilSaved();
    check('offline sharing does not send a premature push',smoke.writes===pushWrites);smoke.offline=false;dispatchEvent(new Event('online'));await wait(()=>smoke.writes>pushWrites);check('shared notification replays after confirmed event upload',true);
    click('#add');click('#addEventKind');document.querySelector('#title').value='Smoke recurring';
    const allDay=document.querySelector('#allDayEvent');allDay.checked=true;allDay.dispatchEvent(new Event('change'));
    const until=new Date(document.querySelector('#eventStartDate').value+'T12:00:00');until.setDate(until.getDate()+2);
    document.querySelector('#repeatUntil').value=[until.getFullYear(),String(until.getMonth()+1).padStart(2,'0'),String(until.getDate()).padStart(2,'0')].join('-');
    document.querySelector('#repeatRule').value='daily';document.querySelector('#repeatRule').dispatchEvent(new Event('change'));document.querySelector('#eventForm').requestSubmit();await untilSaved();await wait(()=>smoke.countEvents('Smoke recurring')===3);check('all-day recurring events save as three occurrences',!!document.querySelector('.allDayEntry'));
    smoke.offline=true;click('#add');click('#addEventKind');document.querySelector('#title').value='Smoke offline event';document.querySelector('#eventForm').requestSubmit();await untilSaved();
    check('offline event is cached before server delivery',!smoke.hasEvent('Smoke offline event')&&document.querySelector('#spaces').textContent.includes('Smoke offline event'));
    smoke.offline=false;dispatchEvent(new Event('online'));await wait(()=>smoke.hasEvent('Smoke offline event'));check('offline queue reconnects without duplicates',smoke.countEvents('Smoke offline event')===1);
    smoke.offline=true;click('#add');click('#addDeadlineKind');document.querySelector('#deadlineTitle').value='Smoke offline deadline';document.querySelector('#deadlineForm').requestSubmit();await wait(()=>!document.querySelector('#deadlineStub').open);
    check('offline deadline retained locally',!smoke.hasEvent('Smoke offline deadline'));const previousWrites=smoke.writes;
    smoke.offline=false;dispatchEvent(new Event('online'));await wait(()=>smoke.hasEvent('Smoke offline deadline')&&smoke.writes>previousWrites);check('offline deadline and reminders replay after reconnect',true);
    click('footer [data-view="tasks"]');check('tasks and deadlines render',!!document.querySelector('.taskComposer')&&!!document.querySelector('.deadlineCard'));
    const taskInput=document.querySelector('.taskComposer input');taskInput.value='Smoke new task';taskInput.form.requestSubmit();await wait(()=>document.querySelector('.taskList').textContent.includes('Smoke new task'));check('task creation',true);
    const due=[...document.querySelectorAll('.deadlineCard')].find(node=>node.textContent.includes('Smoke offline deadline'));due.click();click('#deleteDeadline');await wait(()=>!document.querySelector('#deadlineStub').open);await wait(()=>!smoke.hasEvent('Smoke offline deadline'));check('deadline deletion and reminder cancellation',true);
    click('footer [data-view="all"]');check('all plans render',!!document.querySelector('.dateGroup'));
    click('footer [data-view="day"]');click('#switch');click('#openUpcoming');check('upcoming summary renders',document.querySelector('#upcomingDialog').open);document.querySelector('#upcomingDialog .close').click();
    click('#switch');click('#openProfile');check('profile renders',document.querySelector('#profileDialog').open);
    document.querySelector('#currentPassword').value='old-pass';document.querySelector('#newPassword').value='new-pass';document.querySelector('#confirmPassword').value='different';document.querySelector('#profileForm').requestSubmit();check('password confirmation is checked',document.querySelector('#passwordStatus').className==='error');click('#closeProfile');
    check('no uncaught browser errors',smoke.errors.length===0);
  }catch(error){smoke.errors.push(error.stack||String(error));}
  const result=document.createElement('pre');result.id='smokeResults';result.dataset.result=encodeURIComponent(JSON.stringify(smoke));document.body.append(result);
})();
